{
  "thesis": "投资判断：AI视频生成值得布局，但现有证据更支持优先考察可控生成与垂直工作流，而非仅凭画质领先或融资热度投资通用文生视频模型。2024年的产品集中发布与2025年12月关于工业化生产的行业判断，共同构成品类演进线索，却不足以证明规模化付费需求。建议以客户交付成本、重复付费和扣除重试成本后的贡献利润作为投资前置验证；基础模型公司只有证明质量优势能够持续转化为客户收益，才应获得技术溢价。",
  "evidence_boundary": {
    "scope": "覆盖国内外代表产品，重点比较基础生成、创作工作流与垂直应用；不估算缺乏依据的市场规模、公司收入或估值。",
    "time": "产品功能主要对应2024年阶段；最新明确内容时期为2025年12月，不能作为2026年10月的实时竞争排名。S004和S009没有明确日期。",
    "strength": "四份文本均为研究摘要，缺少原始链接、作者信息、测试方法和可核验财务数据。所载产品参数与行业判断按来源陈述处理，不升级为独立核实事实。",
    "inference": "价格传导、平台分发优势、工作流壁垒和投资排序属于分析推断；客户试点与投资门槛属于建议，不描述为已发生的市场结果。",
    "citation_plan": "正文以报告标题作简短归属，不展示内部来源编号；避免每段重复引用。有关大模型的背景只用于解释竞争机制，不能直接证明视频模型成本或收入。"
  },
  "claims": [
    {
      "claim": "品类催化来自Sora示范及随后密集入场，但融资和产品发布并不等于需求验证。",
      "source": ["S005"],
      "locator": "summary第1段及第2段；key_points第1项",
      "qualification": "仅描述2024年阶段。约12亿元融资是摘要统计，统计口径不详；Runway洽谈融资不能写成融资完成。正文可省略金额，保留供给加速结论。"
    },
    {
      "claim": "AI视频生成不等同于文生视频，还包括图生视频、视频生视频以及围绕视频生产的垂直工具。",
      "source": ["S004"],
      "locator": "summary第1至3段",
      "qualification": "区分生成模型市场与广义视频生产工具，不能将修复、数字人、剪辑等全部收入计入通用视频生成市场。"
    },
    {
      "claim": "Runway、Luma和可灵在早期产品比较中各有优势，单一清晰度排名不足以决定投资价值。",
      "source": ["S004", "S005"],
      "locator": "S004 summary第1段、key_points第2项；S005 summary第2段",
      "qualification": "Runway Gen3、Kling 1.5等为特定版本；测试集、样本量与评分方法缺失。定位比较可用，不能给出当前绝对冠军或推断营收领先。"
    },
    {
      "claim": "字节跳动即梦已在2024年产品描述中提供尾帧控制与图层编辑，其竞争对象不仅是模型，也包括创作入口。",
      "source": ["S005", "S008"],
      "locator": "S005 summary第2段即梦条目；S008 summary第1至2段及key_points第4项",
      "qualification": "即梦功能是历史陈述；字节入口优势属于推断。豆包用户与token规模不能转写为即梦用户、付费转化或视频业务收入，也没有证据确认具体导流效果。"
    },
    {
      "claim": "寻光代表全流程创作平台方向，PixVerse和其他产品则不断增加编辑、连续生成与控制能力。",
      "source": ["S005", "S004"],
      "locator": "S005 summary第2段寻光、PixVerse条目；S004 key_points第5项",
      "qualification": "功能差异只能说明产品路线，不能证明留存或切换成本。工作流是否形成壁垒，需要真实项目使用与协作数据。"
    },
    {
      "claim": "DiT与Transformer相关路线成为重要技术方向，但架构趋同本身不是公司的独占壁垒。",
      "source": ["S004", "S005"],
      "locator": "S004 key_points第1、4项及summary第2段；S005 summary第2段PixVerse条目",
      "qualification": "技术分类来自概括性摘要，不将GAN、VAE、Transformer视为互斥完整架构，也不把架构选择直接等同于性能。数据质量、训练经验及推理优化作为待验证壁垒提出。"
    },
    {
      "claim": "可控性改善是商业使用的重要前提，但物理理解、时序一致性和长视频稳定性仍需要分别验证。",
      "source": ["S004", "S005"],
      "locator": "S004 key_points第5项；S005 key_points第3、5项及summary第1段",
      "qualification": "物理理解缺陷对应当时Sora描述，不能泛化为所有当前产品的已测缺陷。最长续写时长不等于一次性生成时长，更不等于可交付长片长度。"
    },
    {
      "claim": "从画质转向可控性、工作流、低延迟和推理成本的竞争，是合理的产业演进假设。",
      "source": ["S008", "S004", "S005"],
      "locator": "S008 key_points第5项；S004控制工具描述；S005全流程编辑描述",
      "qualification": "S008的视频工业化判断主要出现在关键点中，正文缺少对应客户案例、收入和生产数据，故不能据此宣称工业化采用已经普及。"
    },
    {
      "claim": "通用功能同质化和免费额度可能压低基础生成的付费门槛，并将竞争转向单位可用成片成本。",
      "source": ["S005"],
      "locator": "key_points第3项；summary第2段Dream Machine免费额度描述",
      "qualification": "免费额度属于历史获客安排，不是当前报价。价格压力为机制推断；没有连续价格序列，不能断言已经出现特定降价幅度或毛利下滑。"
    },
    {
      "claim": "大模型平台的资源投入与推理优化可能增强视频生成竞争，但不能直接换算成视频成本下降。",
      "source": ["S009"],
      "locator": "summary腾讯算力投入、DeepSeek部署成本及字节Ultra-Sparse Memory Network段落",
      "qualification": "采购规模与推出时间包含预测，时间基点不明；语言或推理模型的部署成本、内存带宽收益不等于视频模型推理成本。正文只保留平台投入能力和优化方向的背景意义。"
    },
    {
      "claim": "商业化优先验证高频、短片段、可人工复核的生产任务，而非直接承诺替代完整影视制作。",
      "source": ["S004", "S005"],
      "locator": "S004 summary第3段垂直应用；S005 summary第2段各产品片段长度和编辑功能",
      "qualification": "广告素材变体、商品展示和分镜预演是建议试点场景，不是已证实的最佳收入来源。市场需求及愿付价格仍需客户证据。"
    },
    {
      "claim": "投资应以全成本和复购验证为核心，而不是生成次数或演示效果。",
      "source": ["S004", "S005", "S008"],
      "locator": "S004控制能力描述；S005质量和时长瓶颈；S008 key_points第5项",
      "qualification": "属于投资建议。建议口径为单位可用成片成本＝生成与重试、人工筛选修改、后处理及必要授权成本之和除以验收成片数；当前没有数据可代入。"
    }
  ],
  "counterevidence": [
    {
      "challenge": "模型能力仍可能比工作流更重要。",
      "basis": "S004记载产品在清晰度、语义理解和画面表现上存在差异，S005仍将画质和时长列为瓶颈。",
      "implication": "若领先模型在同一真实任务中持续减少重试、提高验收率，基础模型投资优先级应上调；不能预设模型已经商品化。"
    },
    {
      "challenge": "工作流可能只是容易复制的功能组合，而非持久壁垒。",
      "basis": "S004、S005均描述多家公司快速增加编辑和控制功能。",
      "implication": "要求证明项目资产积累、协作习惯和交付数据能够提高留存；若客户无成本多平台切换，则削弱工作流优先论。"
    },
    {
      "challenge": "降价不必然损害投资回报，也可能打开新增需求。",
      "basis": "S005存在免费试用与功能同质化，但没有付费弹性和成本变化数据。",
      "implication": "同时观察净收入、推理支出、重试率和付费频次；若成本下降快于售价且使用增长转化为利润，价格压力可以成为扩张机会。"
    },
    {
      "challenge": "大平台的流量和算力不保证视频产品转化成功。",
      "basis": "S008入口规模描述与S009平台投入信息均未提供视频业务留存或收入数据。",
      "implication": "字节跳动和其他平台的优势只能作为待验证条件，不能据此排除专业独立厂商。"
    },
    {
      "challenge": "行业叙事可能领先于真实采购和生产采用。",
      "basis": "S008提出工业化方向，但四份文本均缺少客户队列、续费、可靠性测试和可核验单位经济数据。",
      "implication": "维持有条件布局，不支持直接作高估值下注；若付费试点无法转为重复生产，应推迟投资。"
    },
    {
      "challenge": "技术可用仍可能无法通过商业验收。",
      "basis": "S005包含物理理解和质量瓶颈；关于版权、肖像、保密、内容审核和授权条款没有直接证据。",
      "implication": "技术问题按历史边界讨论；权利与合规列为待查采用风险，不编造诉讼、监管要求或事故。要求试点覆盖失败样本和返工成本，而非精选演示。"
    }
  ],
  "parts": [
    {
      "number": 1,
      "headings": [
        "# AI视频生成市场投资Memo",
        "## 投资判断",
        "## 市场结构",
        "## 技术壁垒"
      ],
      "target_nonspace_characters": 1900,
      "section_budget": {
        "标题、证据范围及引用": 150,
        "投资判断": 350,
        "市场结构": 700,
        "技术壁垒": 700
      },
      "writing_instructions": "结论先行，说明品类时机与有条件投资立场。市场结构区分通用模型、创作平台、垂直工具；重点比较Runway、Luma、可灵、字节即梦，并以Sora、PixVerse、寻光解释技术催化和产品分化。技术部分将多模态输入、时序稳定、控制能力、推理工程与交付验收联系起来，不堆砌架构名词。保留模型领先可能持续创造价值的反证。",
      "completion_conditions": "有公司间比较、技术到客户收益的机制和历史版本边界；不把产品参数写成当前实测排名，不把生成式AI整体热度当作视频需求。"
    },
    {
      "number": 2,
      "headings": [
        "## 商业化",
        "## 风险与反证"
      ],
      "target_nonspace_characters": 1700,
      "section_budget": {
        "商业化：价格压力、单位经济与GTM": 950,
        "风险与反证：采用障碍及投资触发条件": 650,
        "引用与衔接余量": 100
      },
      "writing_instructions": "商业化以建议试点场景展开：创作者自助试用获取需求反馈，专业团队通过付费项目验证节省工时和验收率，API扩张必须先证明服务稳定与贡献利润。明确使用者、审批者及预算方需要在试点中确认。解释免费额度、同质化、平台分发和算力投入如何形成价格压力，同时提出降本扩需的相反路径。用单位可用成片成本而非每秒标价比较替代方案，纳入传统制作、素材库和人工编辑。最后给出客户复购、交付质量、成本和权利保障四类尽调证据，以及上调、推迟或放弃投资的条件，不设置无依据的数值门槛。",
      "completion_conditions": "价格压力与GTM分开回答；采用风险与投资反证均具体影响决策；所有门槛标为建议，缺失收入、成本、客户及权利证据保持明确，不用缺失数据反推市场不存在。"
    }
  ],
  "length_plan": {
    "total_target_nonspace_characters": 3600,
    "allowed_range": [2500, 4500],
    "counting_convention": "两部分拼接后统计全部非空白字符，包含Markdown标题、标点、英文、数字和引用；不计本JSON分析笔记。",
    "editing_priority": "先保障公司比较、技术机制、价格压力、GTM及反证的深度，再压缩发布日程与重复背景；预留字数用于完整报告衔接。"
  }
}
